#include <bits/stdc++.h>
using namespace std;

long calculate(long n) {
    int limitSize = (int)4e5;
    vector<long> upperArray(limitSize);
    vector<long> lowerArray(limitSize);
    for (int i = 1; i < limitSize; ++i) {
        lowerArray[i] = i;
        upperArray[i] = n / i;
    }
    vector<bool> primeMarkers(limitSize, true);
    primeMarkers[0] = false;
    primeMarkers[1] = false;

    vector<int> primeNumbers;
    for (int i = 2; i < limitSize; ++i) {
        if (!primeMarkers[i]) continue;
        primeNumbers.push_back(i);
        for (int j = i * 2; j < limitSize; j += i) {
            primeMarkers[j] = false;
        }
    }

    for (size_t idx = 0; idx < primeNumbers.size(); ++idx) {
        int p = primeNumbers[idx];
        for (int i = 1; i < limitSize && n / i >= (long long)p * p; ++i) {
            long long val = (long long)p * i;
            if (val < limitSize) {
                upperArray[i] -= (upperArray[(int)val] - (idx + 1));
            } else {
                lowerArray[(int)(n / i / p)] -= (lowerArray[(int)(n / i / p)] - (idx + 1));
            }
        }
        for (int i = limitSize - 1; i >= (long long)p * p; --i) {
            lowerArray[i] -= lowerArray[i / p] - (idx + 1);
        }
    }

    long totalCount = 0;
    for (auto p : primeNumbers) {
        if ((long long)p * p > n) break;
        if ((long long)p * p * p <= n && (long long)p * p * p > 0) {
            totalCount++;
        }
        if (n / p > p) {
            if (p < limitSize)
                totalCount += upperArray[p] - lowerArray[p];
            else
                totalCount += lowerArray[(int)(n / p)] - lowerArray[p];
        }
    }
    return totalCount;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long val;
    cin >> val;
    cout << calculate(val) << "\n";
    return 0;
}

